app.get('/api/wechat/detect-path', (req, res) => {
  const os = require('os');
  const homeDir = os.homedir();

  // macOS 微信数据目录规律
  const wxContainerBase = path.join(homeDir, 'Library/Containers/com.tencent.xinWeChat/Data/Library/Application Support/com.tencent.xinWeChat');

  const detectedPaths = [];

  if (fs.existsSync(wxContainerBase)) {
    try {
      const accounts = fs.readdirSync(wxContainerBase);
      accounts.forEach(account => {
        // 过滤非账号目录
        if (account.startsWith('.')) return;
        const dbDir = path.join(wxContainerBase, account, 'Message/msg_0.db');
        const dbDirAlt = path.join(wxContainerBase, account, 'Message');

        if (fs.existsSync(dbDir)) {
          detectedPaths.push({
            account_hash: account.substring(0, 8) + '****',
            db_path: dbDir,
            type: 'msg_0.db'
          });
        } else if (fs.existsSync(dbDirAlt)) {
          // 探测 Message 目录下所有 .db 文件
          const dbs = fs.readdirSync(dbDirAlt).filter(f => f.endsWith('.db'));
          dbs.forEach(db => {
            detectedPaths.push({
              account_hash: account.substring(0, 8) + '****',
              db_path: path.join(dbDirAlt, db),
              type: db
            });
          });
        }
      });
    } catch (e) {
      console.error('[WeChat Detect] Error scanning:', e.message);
    }
  }

  if (detectedPaths.length === 0) {
    return res.json({
      success: false,
      message: '未检测到微信数据目录。请确认微信已在此 Mac 上登录过，或手动填写数据库路径。',
      paths: []
    });
  }

  res.json({
    success: true,
    message: `成功探测到 ${detectedPaths.length} 个微信数据库文件！`,
    paths: detectedPaths
  });
});

